"""Scanner behavior: planted findings are reported, exempt paths are skipped."""

import unittest

import scan_neutrality
import scan_secrets


class NeutralityContentScan(unittest.TestCase):
    def test_planted_terms_are_reported(self):
        content, _ = scan_neutrality.load_terms(scan_neutrality.DEFAULT_TERMS)
        hits = scan_neutrality.scan_text(
            "This module was generated by an assistant.", content
        )
        patterns = {pattern for _, pattern, _ in hits}
        self.assertTrue(any("generated" in p for p in patterns))
        self.assertTrue(any("assistant" in p for p in patterns))

    def test_clean_text_passes(self):
        content, _ = scan_neutrality.load_terms(scan_neutrality.DEFAULT_TERMS)
        hits = scan_neutrality.scan_text("A framing codec for serial links.", content)
        self.assertEqual(hits, [])

    def test_email_addresses_are_reported(self):
        content, _ = scan_neutrality.load_terms(scan_neutrality.DEFAULT_TERMS)
        hits = scan_neutrality.scan_text(
            "Reach the maintainer role at someone@example.org.", content
        )
        self.assertTrue(hits)

    def test_local_path_is_reported(self):
        content, _ = scan_neutrality.load_terms(scan_neutrality.DEFAULT_TERMS)
        hits = scan_neutrality.scan_text("Copy the file from /home/developer/etc.", content)
        self.assertTrue(hits)


class NeutralityFilenameScan(unittest.TestCase):
    def test_env_style_filename(self):
        _, filenames = scan_neutrality.load_terms(scan_neutrality.DEFAULT_TERMS)
        self.assertTrue(
            scan_neutrality.filename_findings("config/.env.production", filenames)
        )
        self.assertFalse(
            scan_neutrality.filename_findings("config/settings.yaml", filenames)
        )


class NeutralityAllowlist(unittest.TestCase):
    def test_whole_file_exemption(self):
        entries = [{"path": "docs/*", "reason": "fixture"}]
        self.assertTrue(scan_neutrality.whole_file_allowed("docs/notes.md", entries))
        self.assertFalse(scan_neutrality.whole_file_allowed("src/core.py", entries))

    def test_per_term_exemption(self):
        entries = [
            {
                "path": "src/*",
                "reason": "fixture",
                "allow_terms": ["\\bgemini\\b"],
            }
        ]
        self.assertEqual(
            scan_neutrality.permitted_terms("src/a.py", entries), {"\\bgemini\\b"}
        )


class SecretContentScan(unittest.TestCase):
    def test_known_token_format(self):
        line = 'token = "ghp_' + "A1b2C3d4E5f6G7h8I9j0K1l2M3n4O5p6Q7" + '"'
        hits = scan_secrets.scan_line(line)
        self.assertTrue(any(name == "github-token" for name, _ in hits))

    def test_credential_assignment(self):
        line = 'api_key = "' + "k" * 32 + '"'
        hits = scan_secrets.scan_line(line)
        self.assertTrue(any(name == "credential-assignment" for name, _ in hits))

    def test_prose_about_tokens_passes(self):
        hits = scan_secrets.scan_line("The access token is rotated every 30 days.")
        self.assertEqual(hits, [])

    def test_plain_hex_is_not_high_entropy(self):
        hits = scan_secrets.scan_line("digest: " + "0123456789abcdef" * 3)
        self.assertEqual(hits, [])

    def test_random_mixed_string_is_high_entropy(self):
        hits = scan_secrets.scan_line("value Xy7zQ9pL2mN4kJ6hG8fD5sA3wE1rT0yU end")
        self.assertTrue(any(name == "high-entropy-string" for name, _ in hits))


class SecretFilenameScan(unittest.TestCase):
    def test_env_style_filename(self):
        self.assertTrue(scan_secrets.ENV_FILENAME.search("deploy/.env.staging"))
        self.assertFalse(scan_secrets.ENV_FILENAME.search("deploy/settings.py"))


if __name__ == "__main__":
    unittest.main()
